//! Actual all-target effect request/reply boundary. Other checker families retain
//! their independent configured endpoints; this row never claims full parity.
use super::{QueryReply,QueryRequest,SourceQuery};use serde_json::Value;use std::io;
pub(super) fn reads_policy(query:&SourceQuery)->bool{matches!(query,SourceQuery::NativeEffectReports{..})}
fn invalid(why:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidData,format!("invalid original effect reports: {why}"))}
pub(super) fn row_u32(row:&Value,key:&str)->io::Result<u32>{row[key].as_u64().and_then(|n|u32::try_from(n).ok()).ok_or_else(||invalid("window coordinate"))}
pub(super) fn validate_request(request:&QueryRequest)->io::Result<()>{for query in &request.source_queries{if let SourceQuery::NativeEffectReports{environment,configuration,page_width,target_window}=query{if request.expected_policy_revision.is_none()||!environment.is_absolute()||configuration.as_ref().is_some_and(|p|!p.is_absolute())||!(1..=dm_analysis::checker_effects::MAX_EVENTS as u32).contains(page_width)||!(1..=dm_analysis::checker_effects::MAX_EVENTS as u32).contains(target_window){return Err(io::Error::new(io::ErrorKind::InvalidInput,"effect reports require exact captured policy pin, absolute configuration paths and existing bounded windows"))}}}Ok(())}
fn exact(row:&Value,keys:&[&str])->io::Result<()>{let object=row.as_object().ok_or_else(||invalid("not an object"))?;if object.len()!=keys.len()||keys.iter().any(|key|!object.contains_key(*key)){return Err(invalid("payload fields"))}Ok(())}
fn text(value:&Value)->bool{value.as_str().is_some_and(|s|!s.is_empty())}
fn span(value:&Value)->bool{value.as_array().is_some_and(|v|v.len()==2&&matches!((v[0].as_u64(),v[1].as_u64()),(Some(a),Some(b))if a<=b))}
fn point(value:&Value,primary:bool)->io::Result<()>{exact(value,&["file","line","column"])?;if !text(&value["file"])||!value["line"].as_u64().is_some_and(|n|!primary||n>0)||!value["column"].as_u64().is_some_and(|n|!primary||n>0){return Err(invalid("source point"))}Ok(())}
pub(super) fn validate_requested(reply:&QueryReply,questions:&[SourceQuery])->io::Result<()>{let expected:Vec<_>=questions.iter().filter(|q|reads_policy(q)).collect();let mut next=0;for line in reply.jsonl.lines(){let row:Value=serde_json::from_str(line).map_err(|_|invalid("JSONL"))?;if row["row"]!="source_native_effect_reports"{continue}let Some(SourceQuery::NativeEffectReports{environment,configuration,page_width,target_window})=expected.get(next).copied()else{return Err(invalid("extra row"))};exact(&row,&["row","schema","semantic_revision","source_revision","policy_revision","environment","body_count","full_checker_parity","effect_phase_order","target_group_order_contract","configuration","configuration_explicit","configuration_present","configuration_schema","page_width","target_window","target_count","diagnostics","effect_report_only","target_windows_exhausted"])?;let selected=dm_analysis::check_configuration::select(environment,configuration.as_deref());if row["schema"]!="dm-session-source-query-v1"||row["semantic_revision"].as_str()!=Some(reply.revision.as_str())||reply.source_revision.is_none()||row["source_revision"].as_str()!=reply.source_revision.as_deref()||reply.policy_revision.is_none()||row["policy_revision"].as_str()!=reply.policy_revision.as_deref()||row["environment"]!=serde_json::to_value(environment).map_err(io::Error::other)?||row["configuration"]!=serde_json::to_value(&selected.path).map_err(io::Error::other)?||row["configuration_explicit"]!=selected.explicit||!row["configuration_present"].is_boolean()||row["configuration_schema"]!="complete_pinned_checker_schema"||row["page_width"]!=*page_width||row["target_window"]!=*target_window||row["body_count"].as_u64().is_none()||row["target_count"].as_u64().is_none()||row["full_checker_parity"]!=false||row["effect_report_only"]!=true||row["target_windows_exhausted"]!=true||row["effect_phase_order"]!=serde_json::to_value(dm_analysis::checker_effects::EFFECT_PHASE_ORDER).map_err(io::Error::other)?||row["target_group_order_contract"]!=dm_analysis::checker_effects::TARGET_GROUP_ORDER_CONTRACT{return Err(invalid("metadata, scope or false coverage"))}
 let mut previous=0;for diagnostic in row["diagnostics"].as_array().ok_or_else(||invalid("diagnostics"))?{exact(diagnostic,&["phase","registration_tag","family","severity","source","expanded_span","expression_span","message","notes"])?;let phase=match diagnostic["phase"].as_str(){Some("body_immediate")=>0,Some("must_not_sleep")=>1,Some("must_be_pure")=>2,_=>return Err(invalid("phase"))};if phase<previous||!text(&diagnostic["family"])||!text(&diagnostic["message"])||!matches!(diagnostic["severity"].as_str(),Some("error"|"warning"|"info"|"hint"))||!span(&diagnostic["expanded_span"])||!span(&diagnostic["expression_span"])||!(diagnostic["registration_tag"].is_null()||text(&diagnostic["registration_tag"]))||phase==0&&!diagnostic["registration_tag"].is_null()||phase==1&&diagnostic["registration_tag"]!="must_not_sleep"||phase==2&&diagnostic["registration_tag"]!="must_be_pure"{return Err(invalid("diagnostic"))}previous=phase;point(&diagnostic["source"],true)?;for note in diagnostic["notes"].as_array().ok_or_else(||invalid("notes"))?{exact(note,&["message","source"])?;if !text(&note["message"]){return Err(invalid("note message"))}if !note["source"].is_null(){point(&note["source"],false)?;}}}
 next+=1;}if next!=expected.len(){return Err(invalid("missing row"))}Ok(())}
#[cfg(test)]#[path="effect_reports_tests.rs"]mod tests;
